using namespace std; using Pt=pair<long long,long long>; const string W="RRLLLLRLRRRRLRRRRLLLLRLRRRRLRLLRRLLLLRRLLRRRRLLRRLRLLRLLRLRLLRRRRLLRLLRRRRLLRRRRLLRLRRRRLRLLLLRRRRLRRLRR"; const string U="RRLRLLLLRRRRLRRLRRRRLLLLRLRR"; const string A="LLRRRRLRRLRRRRLLLLRLRRRRLRLL"; const string B="RRLLLLRRLLRRRRLLRRLRLLRLLRLRLLRRRRLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRRRRLRLL"; const string T="RRRRLLRLLRRRRLLRRRRLLRLL"; const string C="RRLRRRRLLLLRLRRRRLRRLRRRRLLLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRR"; const int dx[4]={ 0,1,0,-1 },dy[4]={ 1,0,-1,0 }; void need(bool b,const string&m){ if(!b)throw runtime_error(m); } set<string> factors(const string&w,int n){ string s; while(s.size()<w.size()+size_t(n))s+=w; set<string>r; for(size_t i=0;i<w.size();++i)r.insert(s.substr(i,n)); return r; } struct Enum { array<array<int,305>,305>board; set<string>leaves; array<bool,1024>allowed{ }; long long nodes=0; Enum(){ for(auto&r:board)r.fill(-1); for(auto&w:factors(W,10)){ int b=0; for(char c:w)b=(b<<1)|(c=='L'); allowed[b]=true; } }  void run(string&w,int x=0,int y=0,int h=0,int bits=0){ ++nodes; if(w.size()==150){ leaves.insert(w); return; }int old=board[x+152][y+152]; for(int c=0;c<2;++c){ int b=((bits<<1)|c)&1023; if(w.size()>=9&&!allowed[b])continue; if(old!=-1&&old!=c)continue; board[x+152][y+152]=1-c; w+=c?'L':'R'; int g=(h+(c?3:1))%4; run(w,x+dx[g],y+dy[g],g,b); w.pop_back(); board[x+152][y+152]=old; } } }; struct Geom{ vector<Pt>q; Pt d; int h; }; Geom geom(const string&w){ Geom g; long long x=0,y=0; int h=0; for(char c:w){ g.q.push_back({ x,y }); h=(h+(c=='R'?1:3))%4; x+=dx[h]; y+=dy[h]; }g.d={ x,y }; g.h=h; return g; } Pt rot(Pt p,int h){ switch((h%4+4)%4){ case 0:return p; case 1:return { p.second,-p.first }; case 2:return { -p.first,-p.second }; default:return { -p.second,p.first }; } } bool multiple(Pt p,Pt d,long long&s){ long long a=d.first?d.first:d.second,b=d.first?p.first:p.second; if(!a||b%a)return false; s=b/a; return p==Pt{ s*d.first,s*d.second }; } bool feasible(const string&w){ auto g=geom(w); map<Pt,char>last; for(size_t i=0;i<w.size();++i){ if(last.count(g.q[i])&&last[g.q[i]]==w[i])return false; last[g.q[i]]=w[i]; }return true; } vector<pair<long long,char>> visits(long long n,long long m,Pt target){ vector<pair<long long,char>>v; Pt p{ 0,0 }; int h=0; long long start=0; for(auto wr:vector<pair<string,long long>>{ { B,1 },{ A,n },{ B,1 },{ A,m },{ B,1 } }){ auto g=geom(wr.first); Pt d=rot(g.d,h); for(size_t i=0;i<g.q.size();++i){ Pt a=rot(g.q[i],h); a.first+=p.first; a.second+=p.second; Pt diff{ target.first-a.first,target.second-a.second }; long long k=-1; if(wr.second==1){ if(diff==Pt{ 0,0 })k=0; }else if(wr.second>0){ need(g.h==0,"nontranslating power"); if(!multiple(diff,d,k))k=-1; }if(k>=0&&k<wr.second)v.push_back({ start+k*wr.first.size()+i,wr.first[i] }); }p.first+=wr.second*d.first; p.second+=wr.second*d.second; h=(h+wr.second*g.h)%4; start+=wr.second*wr.first.size(); }sort(v.begin(),v.end()); return v; } int supply(){ int all=-999; for(int ph=0;ph<24;++ph){ string w=T.substr(ph)+T.substr(0,ph); auto g=geom(w); using Entry=tuple<long long,int,char>; vector<pair<Pt,vector<Entry>>>classes; for(int i=0;i<24;++i){ bool used=false; for(auto &cl:classes){ long long a; if(multiple({ g.q[i].first-cl.first.first,g.q[i].second-cl.first.second },g.d,a)){ cl.second.push_back({ a,i,w[i] }); used=true; break; } }if(!used)classes.push_back({ g.q[i],{ { 0,i,w[i] } } }); }  vector<long long>finite,rays; for(auto &cl:classes){ auto e=cl.second; sort(e.begin(),e.end(),[](Entry a,Entry b){ return get<0>(a)!=get<0>(b)?get<0>(a)>get<0>(b):get<1>(a)<get<1>(b); }); for(size_t i=1;i<e.size();++i)need(get<2>(e[i])!=get<2>(e[i-1]),"nonalternating T class"); long long lo=get<0>(e.back()),hi=get<0>(e.front()); for(long long n=lo;n<hi;++n)for(auto [a,i,c]:e)if(a<=n){ if(c=='L')finite.push_back((n-a)*24+i); break; }auto [a,i,c]=e.front(); if(c=='L')rays.push_back((hi-a)*24+i); }  need(rays.size()==2,"wrong T seed demand"); long long D=0; for(auto x:finite)D=max(D,x+1); for(auto x:rays)D=max(D,x); for(long long L=0;L<D+24;++L){ int b=0; for(auto x:finite)b+=x<L; for(auto x:rays)if(x<L)b+=(L-1-x)/24+1; all=max(all,int(L-12*b)); } }  need(all==5,"supply bound"); return all; } set<int> closure(const vector<vector<int>>&adj,set<int>start){ vector<int>todo(start.begin(),start.end()); while(!todo.empty()){ int a=todo.back(); todo.pop_back(); for(int b:adj[a])if(start.insert(b).second)todo.push_back(b); }return start; } int main(int argc,char**argv){ try{ string dir=argc>1?argv[1]:"certificates"; Enum en; string w; en.run(w); ifstream f(dir+"/windows10.txt"); need(bool(f),"missing words"); set<string>supplied; size_t lines=0; while(getline(f,w)){ need(w.size()==150,"wrong edge length"); supplied.insert(w); ++lines; }need(lines==supplied.size()&&supplied==en.leaves,"incomplete or incorrect words"); set<string>names; for(auto&w:supplied){ names.insert(w.substr(0,149)); names.insert(w.substr(1)); }vector<string>label(names.begin(),names.end()); map<string,int>id; for(size_t i=0;i<label.size();++i)id[label[i]]=i; int N=label.size(); vector<vector<int>>adj(N),rev(N); for(auto&w:supplied){ int a=id.at(w.substr(0,149)),b=id.at(w.substr(1)); adj[a].push_back(b); rev[b].push_back(a); }vector<int>seen(N),order,ci(N,-1); function<void(int)>dfs=[&](int v){ seen[v]=1; for(int u:adj[v])if(!seen[u])dfs(u); order.push_back(v); }; for(int v=0;v<N;++v)if(!seen[v])dfs(v); vector<set<int>>comps; function<void(int,int)>back=[&](int v,int c){ ci[v]=c; comps[c].insert(v); for(int u:rev[v])if(ci[u]<0)back(u,c); }; reverse(order.begin(),order.end()); for(int v:order)if(ci[v]<0){ comps.emplace_back(); back(v,comps.size()-1); }set<int>SW,ST,H; for(auto&w:factors(W,149))SW.insert(id.at(w)); for(auto&w:factors(T,149))ST.insert(id.at(w)); vector<int>cyclic; for(auto&c:comps){ bool loop=c.size()>1; for(int v:c)for(int u:adj[v])loop|=(u==v); if(loop){ cyclic.push_back(c.size()); if(c!=SW&&c!=ST){ need(H.empty(),"extra SCC"); H=c; } } }sort(cyclic.begin(),cyclic.end()); need(cyclic==vector<int>({ 24,104,366 }),"wrong recurrent graph"); need(N==6501&&supplied.size()==6605,"wrong complete graph"); for(auto c:{ SW,ST })for(int v:c){ int n=0; for(int u:adj[v])n+=c.count(u); need(n==1,"not simple"); }  map<int,int>mp; ifstream qf(dir+"/quotient.tsv"); need(bool(qf),"missing quotient"); int state; while(qf>>w>>state){ int v=id.at(w); need(!mp.count(v),"duplicate map"); mp[v]=state; }need(mp.size()==H.size(),"wrong map size"); for(int v:H)need(mp.count(v)&&mp[v]>=0&&mp[v]<102,"incomplete quotient"); need(A.substr(1)==B.substr(75)&&A[0]=='L'&&B[0]=='R',"wrong bouquet words"); int checked=0; for(int v:H)for(int u:adj[v])if(H.count(u)){ int a=mp.at(v),b=mp.at(u); char c=label[u].back(); int target=(a==0&&c=='L')?75:(B[a]==c?(a+1)%102:-1); need(target==b,"bad quotient edge"); ++checked; }need(checked==370,"quotient count"); set<int>anc=closure(rev,SW); need(anc.size()==925,"wrong standard ancestors"); for(int v:H)need(!anc.count(v),"fold SCC reaches standard"); set<int>pre=closure(rev,ST); for(int v:ST)pre.erase(v); need(pre.size()==54,"wrong prefix set"); vector<int>memo(N,-100000),active(N); function<int(int)>weighted=[&](int v){ if(memo[v]!=-100000)return memo[v]; need(!active[v],"prefix cycle"); active[v]=1; int rest=-100000; for(int u:adj[v])if(ST.count(u))rest=max(rest,0); else if(pre.count(u))rest=max(rest,weighted(u)); need(rest>-100000,"bad prefix endpoint"); active[v]=0; return memo[v]=1+(label[v][0]=='R'?12:-12)+rest; }; int before=0; for(int v:pre)before=max(before,weighted(v)); need(before==70,"weighted prefix"); set<int>post=closure(adj,ST); for(auto it=post.begin();it!=post.end();){ int v=*it; if(!anc.count(v)||SW.count(v)||ST.count(v))it=post.erase(it); else++it; }fill(memo.begin(),memo.end(),-1); fill(active.begin(),active.end(),0); function<int(int)>length=[&](int v){ if(memo[v]>=0)return memo[v]; need(!active[v],"suffix cycle"); active[v]=1; int z=0; for(int u:adj[v])if(post.count(u))z=max(z,length(u)); active[v]=0; return memo[v]=z+1; }; int after=0; for(int v:ST)for(int u:adj[v])if(post.count(u))after=max(after,length(u)); need(after==137,"suffix bound"); set<int> noT=anc; for(int v:SW)noT.erase(v); for(int v:ST)noT.erase(v); fill(memo.begin(),memo.end(),-1); fill(active.begin(),active.end(),0); function<int(int)> direct=[&](int v){ if(memo[v]>=0)return memo[v]; need(!active[v],"no-T cycle"); active[v]=1; int z=0; for(int u:adj[v])if(noT.count(u))z=max(z,direct(u)); active[v]=0; return memo[v]=z+1; }; int noTmax=0; for(int v:noT)noTmax=max(noTmax,direct(v)); need(noTmax==167,"no-T length bound"); int demand=supply(); need(before+after+demand==212,"attraction intercept"); long long nc=0; for(long long n=0;n<45;++n)for(long long m=0;m<45;++m){ Pt p; long long a,b; if(n==0){ p={ 0,2 }; a=32; b=184; }else if(m>=n){ p={ 0,2 }; a=32; b=184+56*n; }else{ p={ 1,4*(n-m) }; a=25+28*(n-m); b=205+28*(n+m); }auto v=visits(n,m,p); auto it=find(v.begin(),v.end(),make_pair(a,'R')); need(it!=v.end()&&it+1!=v.end()&&*(it+1)==make_pair(b,'R'),"fold collision"); ++nc; }  need(geom(A).d==Pt(0,-4)&&geom(A).h==0&&geom(B).d==Pt(1,11)&&geom(B).h==2,"fold poses"); need(geom(C).d==Pt(13,-4)&&geom(C).h==3&&feasible(U+C+U),"spiral junction"); string local=U+U+C+U+U; auto a9=factors(W,9); for(size_t i=0;i+9<=local.size();++i)need(a9.count(local.substr(i,9)),"spiral nine-factor"); need(!factors(W,10).count("RLRRRRLRRL"),"missing ten-factor"); cout<<"{\"status\":\"passed\",\"implementation\":\"independent C++17 live-colour DFS, SCC, quotient and supply\",\"enumeration_nodes\":"<<en.nodes<<",\"vertices\":"<<N<<",\"edges\":"<<supplied.size()<<",\"quotient_edges\":"<<checked<<",\"pre_weight\":"<<before<<",\"post_length\":"<<after<<",\"no_T_length\":"<<noTmax<<",\"supply\":"<<demand<<",\"intercept\":212,\"fold_controls\":"<<nc<<",\"HC_proved\":false}\n"; return 0; }catch(const exception&e){ cerr<<"REJECTED: "<<e.what()<<'\n'; return 1; } }
